const nav=[['dashboard','▦'],['inventory','▤'],['transactions','⇄'],['transfers','⇆'],['vouchers','▧'],['reports','▥'],['facilities','⌂'],['stocktake','◫'],['settings','⚙'],['about','ⓘ']];
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function field(label,html,full=false){return `<div class="field ${full?'full':''}"><label>${esc(label)}</label>${html}</div>`}
function input(label,placeholder='',type='text',full=false){return field(label,`<input type="${type}" placeholder="${esc(placeholder)}">`,full)}
function select(label,opts=['اختر...'],full=false){return field(label,`<select>${opts.map(x=>`<option>${esc(x)}</option>`).join('')}</select>`,full)}
function empty(title=T().noData,note=''){return `<div class="empty"><strong>${esc(title)}</strong><span>${esc(note)}</span></div>`}
function card(title,body,actions=''){return `<section class="card"><div class="card-head"><div class="card-title">${esc(title)}</div>${actions}</div><div class="card-body">${body}</div></section>`}
function table(headers,rows=[],emptyTitle=T().noData){const rowHtml=Array.isArray(rows)?rows.join(''):(typeof rows==='string'?rows:'');const hasRows=Array.isArray(rows)?rows.length>0:typeof rows==='string'&&rows.trim().length>0;return `<div class="table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${hasRows?rowHtml:`<tr><td colspan="${headers.length}">${empty(emptyTitle)}</td></tr>`}</tbody></table></div>`}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><h1 class="page-title">${esc(title)}</h1><p class="page-subtitle">${esc(sub||'')}</p></div><div class="actions">${actions}</div></div>`}
function stat(label,value,note,icon){return `<div class="card stat"><div class="stat-icon">${icon}</div><div class="stat-label">${esc(label)}</div><div class="stat-value">${esc(value)}</div><div class="stat-note">${esc(note)}</div></div>`}
function modal(title,body,actions=''){const wide=String(body||'').includes('id="v12-tx-form"');return `<div class="modal-backdrop" data-close-modal><div class="modal ${wide?'modal-wide v13-transaction-modal':''}"><div class="modal-head"><div class="modal-title">${esc(title)}</div><button class="icon-btn" data-action="close-modal">×</button></div><div class="modal-body">${body}${actions?`<div class="form-actions">${actions}</div>`:''}</div></div></div>`}
function toast(msg,type='success'){const root=document.getElementById('toast-root');const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=msg;root.appendChild(el);setTimeout(()=>el.remove(),2800)}
function authInput(label,name,placeholder,type='text',autocomplete=''){const isPassword=name==='password';return `<div class="field ${isPassword?'auth-password-field':''}"><label>${esc(label)}</label><div class="auth-input-wrap"><input name="${esc(name)}" type="${esc(type)}" placeholder="${esc(placeholder)}" autocomplete="${esc(autocomplete||name)}" ${isPassword?'data-password-input aria-describedby="password-visibility-help"':''} required>${isPassword?`<button class="password-visibility" type="button" data-action="v13-toggle-password" aria-label="${state.lang==='ar'?'إظهار كلمة المرور':'Show password'}" aria-pressed="false" title="${state.lang==='ar'?'إظهار كلمة المرور':'Show password'}"><span aria-hidden="true">◉</span></button><span id="password-visibility-help" class="sr-only">${state.lang==='ar'?'إظهار أو إخفاء كلمة المرور':'Show or hide password'}</span>`:''}</div></div>`}

