function v13DisplayTransactionType(value,ar=state.lang==='ar'){const key=String(value||'').toUpperCase();const arNames={GRN:'توريد',ISSUE:'صرف',ADJUSTMENT_IN:'تسوية زيادة',ADJUSTMENT_OUT:'تسوية نقص',OPENING_BALANCE:'رصيد افتتاحي',TRANSFER:'تحويل مخزني',TRANSFER_OUT:'تحويل صادر',TRANSFER_IN:'تحويل وارد',TRANSFER_RETURN:'مرتجع تحويل',RETURN_TO_LOCATION:'مرتجع إلى المخزن',RETURN_TO_SUPPLIER:'مرتجع إلى المورد',RETURN_FROM_USAGE:'مرتجع من جهة الاستخدام',RETURN_FROM_CUSTOMER:'مرتجع من عميل',RECEIPT:'توريد',RECEIVING:'توريد',STOCKTAKE:'الجرد',STOCKTAKE_ADJUSTMENT:'تسوية الجرد',STOCK_TRANSFER:'تحويل مخزني'};const enNames={GRN:'Goods receipt',ISSUE:'Issue',ADJUSTMENT_IN:'Adjustment increase',ADJUSTMENT_OUT:'Adjustment decrease',OPENING_BALANCE:'Opening balance',TRANSFER:'Stock transfer',TRANSFER_OUT:'Transfer out',TRANSFER_IN:'Transfer in',TRANSFER_RETURN:'Transfer return',RETURN_TO_LOCATION:'Return to warehouse',RETURN_TO_SUPPLIER:'Return to supplier',RETURN_FROM_USAGE:'Return from user department',RETURN_FROM_CUSTOMER:'Customer return',RECEIPT:'Goods receipt',RECEIVING:'Goods receipt',STOCKTAKE:'Stocktake',STOCKTAKE_ADJUSTMENT:'Stocktake adjustment',STOCK_TRANSFER:'Stock transfer'};return (ar?arNames:enNames)[key]||String(value||'—')}
function v13DisplayTransactionRecordType(record,ar=state.lang==='ar'){if(!record)return v13DisplayTransactionType('',ar);const raw=String(record.transaction_type||'').toUpperCase();const ref=String(record.reference_no||'').toUpperCase();const note=String(record.notes||'').toLowerCase();const transferOut=raw==='TRANSFER_OUT'||(/-OUT$/.test(ref)&&/^TRF[-_]/.test(ref))||note.includes('direction=out')||note.includes('transfer issue finalized')||note.trim()==='stock_transfer';const transferIn=raw==='TRANSFER_IN'||(/-IN$/.test(ref)&&/^TRF[-_]/.test(ref))||note.includes('stock_transfer_receipt')||note.includes('direction=received')||note.includes('transfer received');const isTransferReturn=raw==='TRANSFER_RETURN'||/RET(?:URN)?[-_ ]?(?:RCV|RECEIPT|RECEIVED)|-RET-RCV|RETURN-RECEIPT/.test(ref)||/returned transfer quantity|transfer return|return receipt|direction=return_received|مرتجع تحويل|استلام مرتجع|إرجاع تحويل/.test(note);if(isTransferReturn)return ar?'مرتجع تحويل':'Transfer return';if(transferOut)return ar?'تحويل صادر':'Transfer out';if(transferIn)return ar?'تحويل وارد':'Transfer in';if(raw==='ADJUSTMENT_IN')return ar?'تسوية زيادة':'Adjustment increase';if(raw==='ADJUSTMENT_OUT')return ar?'تسوية نقص':'Adjustment decrease';return v13DisplayTransactionType(raw,ar);}
function v13DisplayStatus(value,ar=state.lang==='ar'){const key=String(value||'').toUpperCase();const arNames={DRAFT:'مسودة',PENDING:'قيد الانتظار',PENDING_APPROVAL:'بانتظار الاعتماد',APPROVED:'معتمد',REJECTED:'مرفوض',CANCELLED:'ملغى',COMPLETED:'مكتمل',IN_PROGRESS:'قيد التنفيذ',CLOSED:'مغلق',POSTED:'مرحل',FAILED:'فشل',SYNCED:'تمت المزامنة',IN_TRANSIT:'قيد النقل',PARTIALLY_RECEIVED:'مستلم جزئياً',RETURN_IN_TRANSIT:'مرتجع قيد النقل',RECEIVED:'تم الاستلام',RETURNED_TO_SOURCE:'أعيد إلى المصدر',PENDING_REVIEW:'بانتظار المراجعة',SUBMITTED:'مقدم للمراجعة',OPEN:'مفتوح'};const enNames={DRAFT:'Draft',PENDING:'Pending',PENDING_APPROVAL:'Pending approval',APPROVED:'Approved',REJECTED:'Rejected',CANCELLED:'Cancelled',COMPLETED:'Completed',IN_PROGRESS:'In progress',CLOSED:'Closed',POSTED:'Posted',FAILED:'Failed',SYNCED:'Synced',IN_TRANSIT:'In transit',PARTIALLY_RECEIVED:'Partially received',RETURN_IN_TRANSIT:'Return in transit',RECEIVED:'Received',RETURNED_TO_SOURCE:'Returned to source',PENDING_REVIEW:'Pending review',SUBMITTED:'Submitted for review',OPEN:'Open'};return (ar?arNames:enNames)[key]||String(value||'—')}
function v13PrintSurface(title,content){const ar=state.lang==='ar',dir=ar?'rtl':'ltr',w=window.open('','_blank');if(!w){toast(ar?'اسمح بفتح نافذة الطباعة ثم أعد المحاولة':'Allow the print window and try again','warning');return}const safeTitle=esc(title);w.document.open();w.document.write(`<!doctype html><html lang="${ar?'ar':'en'}" dir="${dir}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${safeTitle}</title><style>body{font-family:Arial,Tahoma,sans-serif;color:#172033;margin:14mm;direction:${dir};font-size:12px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #12385a;padding-bottom:12px;margin-bottom:18px}h1{font-size:20px;margin:0 0 5px}small{color:#64748b}.doc-meta{display:flex;gap:18px;flex-wrap:wrap;margin:14px 0}.doc-meta div{padding:8px 12px;border:1px solid #dbe2ea;border-radius:8px}table{border-collapse:collapse;width:100%;margin-top:12px}th,td{border:1px solid #dbe2ea;padding:8px;text-align:start}th{background:#eef3f8}.print-note{margin-top:22px;padding-top:10px;border-top:1px solid #dbe2ea;color:#64748b;font-size:10px}@page{size:auto;margin:12mm}@media print{body{margin:0}button{display:none}}</style></head><body><header><div><h1>ORSHAP WMS</h1><small>${ar?'مستند تشغيلي':'Operational document'}</small></div><div>${new Date().toLocaleString(ar?'ar':'en')}</div></header><h1>${safeTitle}</h1><main>${content}</main><div class="print-note">${ar?'تم إنشاء هذا المستند من نظام إدارة المستودعات.':'Generated by the Warehouse Management System.'}</div><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),250));<\/script></body></html>`);w.document.close()}
function v13PrintCurrentPage(){const page=document.querySelector('.main .page');if(!page)return;const clone=page.cloneNode(true);clone.querySelectorAll('button,.actions,.filters input,.filters select,.icon-btn').forEach(x=>x.remove());v13PrintSurface(state.lang==='ar'?'تقرير النظام':'System report',clone.innerHTML)}
function v13PrintTransactionDraft(){const form=document.getElementById('v12-tx-form');if(!form)return;const o=Object.fromEntries(new FormData(form).entries()),lines=state.v12TxLines||[],ar=state.lang==='ar';const rows=lines.map((l,i)=>{const item=v5Find('items',l.item_id)||{},sh=v5Find('shelves',l.shelf_id)||{};return `<tr><td>${i+1}</td><td>${esc(item.code||'—')} — ${esc((v5Find('items',l.item_id)||{}).name_ar||(v5Find('items',l.item_id)||{}).name_en||'')}</td><td>${esc(sh.code||'—')}</td><td>${Number(l.quantity||0).toLocaleString()}</td><td>${esc(l.batch_no||'—')}</td></tr>`}).join('');const content=`<div class="doc-meta"><div><small>${ar?'رقم المرجع':'Reference'}</small><br><b>${esc(o.reference_no||'—')}</b></div><div><small>${ar?'نوع المعاملة':'Transaction type'}</small><br><b>${esc(v13DisplayTransactionType(o.transaction_type,ar))}</b></div><div><small>${ar?'المورد / المستلم':'Supplier / Receiver'}</small><br><b>${esc(o.supplier||o.receiver_name||'—')}</b></div><div><small>${ar?'الجهة المستلمة فعلياً':'Actual receiving department'}</small><br><b>${esc(v5Find('administrative_departments',o.administrative_department_id)?.name|| (ar?'المخزن العام':'General warehouse'))}</b></div></div><table><thead><tr><th>${ar?'#':'#'}</th><th>${ar?'الصنف':'Item'}</th><th>${ar?'الرف':'Shelf'}</th><th>${ar?'الكمية':'Quantity'}</th><th>${ar?'التشغيلة':'Batch'}</th></tr></thead><tbody>${rows||`<tr><td colspan="5">${ar?'لم تتم إضافة أصناف':'No items added'}</td></tr>`}</tbody></table><p>${ar?'ملاحظات':'Notes'}: ${esc(o.notes||'—')}</p><p>${ar?'إعداد':'Prepared by'}: ${esc(state.session?.profile?.display_name||state.session?.profile?.name||state.session?.user?.email||'—')}　　${ar?'الاعتماد':'Approval'}: __________________</p>`;v13PrintSurface(ar?'معاينة سند المعاملة':'Transaction document preview',content)}
function v13PrintSavedTransaction(id){const x=v5Find('transactions',id);if(!x||!orshapCanPermission('table:transactions:view')||!v13CanViewTransactionRecord(x)){say(state.lang==='ar'?'ليست لديك صلاحية طباعة هذا السند':'You do not have permission to print this voucher','Access denied','error');return}const lines=v5All('transaction_lines').filter(l=>l.transaction_id===id),ar=state.lang==='ar',dept=lines.map(l=>l.administrative_department_id&&v5Find('administrative_departments',l.administrative_department_id)?.name).find(Boolean);const rows=lines.map((l,i)=>`<tr><td>${i+1}</td><td>${esc(v5Find('items',l.item_id)?.code||'—')} — ${esc((v5Find('items',l.item_id)||{}).name_ar||(v5Find('items',l.item_id)||{}).name_en||'')}</td><td>${esc((v5Find('shelves',l.shelf_id)||{}).code||(v5Find('shelves',l.shelf_id)||{}).full_path||'—')}</td><td>${Number(l.quantity||0).toLocaleString()}</td><td>${esc(l.batch_no||'—')}</td><td>${esc(l.expiry_date||'—')}</td></tr>`).join('');const content=`<div class="doc-meta"><div><small>${ar?'رقم المرجع':'Reference'}</small><br><b>${esc(x.reference_no||'—')}</b></div><div><small>${ar?'نوع المعاملة':'Transaction type'}</small><br><b>${esc(v13DisplayTransactionRecordType(x,ar))}</b></div><div><small>${ar?'الحالة':'Status'}</small><br><b>${esc(v13DisplayStatus(x.status,ar))}</b></div><div><small>${ar?'المستودع':'Warehouse'}</small><br><b>${esc((v5Find('warehouses',x.warehouse_id)||{}).name||'—')}</b></div><div><small>${ar?'الجهة المستلمة فعلياً':'Actual receiving department'}</small><br><b>${esc(dept||(ar?'المخزن العام':'General warehouse'))}</b></div></div><table><thead><tr><th>#</th><th>${ar?'الصنف':'Item'}</th><th>${ar?'الرف':'Shelf'}</th><th>${ar?'الكمية':'Quantity'}</th><th>${ar?'التشغيلة':'Batch'}</th><th>${ar?'الصلاحية':'Expiry'}</th></tr></thead><tbody>${rows}</tbody></table><p>${ar?'الملاحظات':'Notes'}: ${esc(x.notes||'—')}</p><div style="display:flex;justify-content:space-between;gap:24px;margin-top:40px"><span>${ar?'إعداد':'Prepared by'}: __________________</span><span>${ar?'اعتماد':'Approved by'}: __________________</span></div>`;v13PrintSurface(ar?'سند مخزني':'Inventory voucher',content)}
function renderLogin(){const ar=state.lang==='ar',t=T();return `<main class="login login-modern"><section class="login-card login-card-modern"><div class="login-form-panel"><div class="login-brand login-brand-modern"><div class="brand-mark">OW</div><div><h1>ORSHAP WMS</h1><p>${ar?'إدارة المستودعات والعمليات':'Warehouse & Operations Management'}</p></div></div><div class="login-welcome"><span class="login-eyebrow">${ar?'بوابة العمل المؤسسي':'ENTERPRISE WORKSPACE'}</span><h2>${state.loginMode==='login'?(ar?'مرحباً بعودتك':'Welcome back'):(ar?'إنشاء حساب جديد':'Create your account')}</h2><p>${state.loginMode==='login'?(ar?'سجّل الدخول لمتابعة المخزون والمعاملات بأمان.':'Sign in to securely manage inventory and transactions.'):(ar?'أدخل بياناتك لطلب إنشاء حساب.':'Enter your details to request an account.')}</p></div><form id="auth-form" novalidate>${state.loginMode==='signup'?authInput(t.fullName,'fullName',t.fullName,'text','name'):''}${authInput(t.email,'email',ar?'name@company.com':'name@company.com','email','email')}${authInput(t.password,'password',ar?'أدخل كلمة المرور':'Enter your password','password','current-password')}<div class="login-actions"><button class="btn primary login-submit" type="submit">${state.loginMode==='login'?t.login:t.signup}<span aria-hidden="true">${ar?'←':'→'}</span></button><button class="btn ghost" type="button" data-action="toggle-auth">${state.loginMode==='login'?(ar?'ليس لديك حساب؟ إنشاء حساب':'Need an account? Create account'):(ar?'لديك حساب؟ تسجيل الدخول':'Already have an account? Sign in')}</button></div><div id="auth-feedback" role="status" aria-live="polite" style="display:none;margin-top:12px;padding:10px 12px;border-radius:10px;white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px"></div></form><div class="login-preferences"><button class="btn ghost" data-action="toggle-lang">${ar?'EN':'العربية'}</button><button class="btn ghost" data-action="toggle-theme">${state.theme==='light'?(ar?'الوضع الداكن':'Dark mode'):(ar?'الوضع الفاتح':'Light mode')}</button></div><small class="login-secure-note">${ar?'جلسة محمية • تُطبّق الصلاحيات من النظام':'Protected session • Access is governed by your assigned role'}</small></div><aside class="login-visual-panel"><div class="login-visual-grid"></div><div class="login-visual-top"><span class="login-orb">OW</span><span>ORSHAP <b>WMS</b></span></div><div class="login-visual-content"><span class="login-visual-kicker">${ar?'وضوح تشغيلي. ضبط محاسبي.':'OPERATIONAL CLARITY.'}</span><h2>${ar?'كل حركة مخزنية،\nبرؤية أوضح.':'Every stock movement,\nwith greater clarity.'}</h2><p>${ar?'من الاستلام إلى الصرف والجرد، اجمع العمليات والرقابة في مساحة عمل واحدة.':'From receiving to issuing and stocktake, bring operations and control into one workspace.'}</p><div class="login-visual-stats"><div><span>01</span><b>${ar?'تتبع':'Traceability'}</b></div><div><span>02</span><b>${ar?'اعتماد':'Approval'}</b></div><div><span>03</span><b>${ar?'تدقيق':'Audit'}</b></div></div></div><div class="login-visual-footer"><span>${ar?'منصة إدارة المخزون':'Inventory operations platform'}</span><span>v13.9.58</span></div></aside></section></main>`}
