function topbar(){const t=T(),returnCount=typeof trfPendingReturnRequests==='function'?trfPendingReturnRequests().length:0;return `<header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-only" data-action="noop">☰</button><div class="breadcrumb" style="font-size:11px;font-weight:800;color:var(--muted)">ORSHAP / ${esc(t[state.page])}</div></div><div class="topbar-right"><span class="badge green">● ${t.online}</span><button class="icon-btn" data-action="toggle-theme">${state.theme==='light'?'☾':'☀'}</button><button class="icon-btn" data-action="toggle-lang">${state.lang==='ar'?'EN':'ع'}</button><button class="icon-btn v13-notification-btn" data-action="${returnCount?'trf-open-returns':'v13-notifications'}" aria-label="${state.lang==='ar'?'الإشعارات':'Notifications'}" title="${returnCount?(state.lang==='ar'?'طلبات إرجاع معلقة':'Pending return requests'):(state.lang==='ar'?'الإشعارات':'Notifications')}">♢${returnCount?`<span class="v13-notification-count">${returnCount}</span>`:''}</button></div></header>`}
function dashboard(){const t=T();const rows=[];return pageHead(t.dashboard,state.lang==='ar'?'نظرة تشغيلية على المخزون والمعاملات':'Real-time operational overview',`<button class="btn success" data-action="open-inbound">＋ ${t.createGRN}</button><button class="btn primary" data-action="open-outbound">＋ ${t.createIssue}</button>`)+`<div class="grid grid-4">${stat(t.totalStock,'0',state.lang==='ar'?'وحدات مسجلة محلياً':'Local stock units','▦')}${stat(t.lowStock,'0',state.lang==='ar'?'تحتاج إلى مراجعة':'Require review','!')}${stat(t.pending,'0',state.lang==='ar'?'معاملة قيد الموافقة':'Transactions pending','↻')}${stat(t.system,'OK',state.lang==='ar'?'حالة النظام':'System status','✓')}</div><div class="grid grid-2" style="margin-top:16px">${card(t.recentActivity,table([t.date,t.user,t.type,t.warehouse,t.name,t.qty,t.opening,t.current],rows))}${card(t.notifications,`<div class="callout danger">${t.criticalStock}<br><b>0</b> ${state.lang==='ar'?'أصناف حرجة':'critical items'}</div><div style="height:10px"></div><div class="callout warning">${state.lang==='ar'?'المعاملات التي تحتاج إجراء':'Transactions requiring action'}<br><b>0</b></div>`)}</div>`}
function inventory(){const t=T();const areaLabel=state.lang==='ar'?'منطقة التخزين':'Storage area',categoryLabel=state.lang==='ar'?'تصنيف الصنف':'Item category';return pageHead(t.inventory,state.lang==='ar'?'إدارة دليل الأصناف والأرصدة حسب المواقع':'Item catalogue and location-based stock balances',`<button class="btn primary" data-action="open-item">＋ ${t.addItem}</button><button class="btn ghost" data-action="print-all">${t.print}</button>`)+`<div class="card"><div class="card-body"><div class="filters"><div class="search field"><span>⌕</span><input placeholder="${t.search}"></div><select><option>${t.warehouse}</option></select><select><option>${areaLabel}</option></select><select><option>${categoryLabel}</option></select><select><option>${t.shelf}</option></select></div>${table([t.sku,t.name,t.unit,t.warehouse,areaLabel,categoryLabel,t.shelf,t.current||'الرصيد',t.safetyStock,t.actions],[],t.noData)}</div></div>`}
function transactions(){const t=T();return pageHead(t.transactions,state.lang==='ar'?'مراجعة واعتماد معاملات المخزون':'Review and approve inventory transactions',`<button class="btn primary" data-action="open-outbound">＋ ${t.newReq}</button>`)+`<div class="tabs"><button class="tab active">${state.lang==='ar'?'الكل':'All'}</button><button class="tab">${t.pending}</button><button class="tab">${t.approved}</button><button class="tab">${t.rejected}</button></div><div class="card" style="margin-top:14px">${table([t.refNo,t.type,t.warehouse,t.user,t.date,t.status,t.actions],[],t.noData)}</div>`}
function facilities(){const t=T(),areaLabel=state.lang==='ar'?'مناطق التخزين':'Storage areas';return pageHead(t.facility,state.lang==='ar'?'إدارة المستودعات ومناطق التخزين والرفوف':'Manage warehouses, storage areas and shelves',`<button class="btn primary" data-action="open-warehouse">＋ ${t.addWarehouse}</button><button class="btn secondary" data-action="v8-open-area">＋ ${state.lang==='ar'?'إضافة منطقة تخزين':'Add storage area'}</button><button class="btn secondary" data-action="open-shelf">＋ ${t.addShelf}</button>`)+`<div class="grid grid-3"><div class="card"><div class="card-head"><span class="card-title">${t.warehouse}</span><button class="btn sm ghost" data-action="open-warehouse">＋</button></div><div class="card-body">${empty(t.noData,state.lang==='ar'?'أضف مستودعاً لبدء بناء الهيكل':'Add a warehouse to build the hierarchy')}</div></div><div class="card"><div class="card-head"><span class="card-title">${areaLabel}</span><button class="btn sm ghost" data-action="v8-open-area">＋</button></div><div class="card-body">${empty(t.noData)}</div></div><div class="card"><div class="card-head"><span class="card-title">${t.shelvesQR}</span><button class="btn sm ghost" data-action="open-shelf">＋</button></div><div class="card-body">${empty(t.noData)}</div></div></div><div class="card" style="margin-top:16px">${table([t.code,t.name,t.warehouse,areaLabel,t.shelf,t.actions],[],t.noData)}</div>`}
