function settings(){const t=T();return pageHead(t.settings,state.lang==='ar'?'إدارة المستخدمين وتهيئة النظام والتكاملات':'Users, system configuration and tools');return ''}
function settingsFull(){
  const t=T();
  const usersCard=card(t.users,
    table([t.fullName,t.email,t.role||'Role',t.status,t.actions],[],t.noData),
    `<button class="btn sm primary" data-action="open-user">＋ ${t.add}</button>`
  );
  const systemCard=card(t.systemConfig,
    `<div class="form-grid">${input(t.fullName,'ORSHAP WMS')}${input(t.email,'support@company.com','email')}${select(t.status,['ACTIVE','PENDING','DISABLED'])}${select(t.syncStrategy,[state.lang==='ar'?'مزامنة تلقائية':'Automatic sync'])}</div><div class="form-actions"><button class="btn primary" data-action="save-settings">${t.save}</button></div>`
  );
  const unitsCard=card(t.units,
    `<div class="actions"><button class="btn primary" data-action="open-unit">＋ ${t.add}</button></div>${table([t.code,t.name,t.baseUnit,t.purchaseUnit,t.conversion,t.actions],[],t.noData)}`
  );
  const appearanceCard=card(t.appearance,
    `<div class="form-grid">${select(state.lang==='ar'?'السمة':'Theme',['Light','Dark'])}${select(state.lang==='ar'?'حدود الجداول':'Table borders',['Enabled','Disabled'])}</div>`,
    `<button class="btn primary" data-action="save-settings">${t.save}</button>`
  );
  const printCard=card(t.printConfig,
    `<div class="form-grid">${input(state.lang==='ar'?'اسم الشركة':'Company Name','ORSHAP WMS')}${input(state.lang==='ar'?'رقم الهاتف':'Phone')}${input(state.lang==='ar'?'العنوان':'Address',state.lang==='ar'?'العنوان':'Address','text',true)}</div>`
  );
  const dataCard=card(t.dataTools,
    `<div class="actions"><button class="btn ghost" data-action="import">${t.import}</button><button class="btn ghost" data-action="export">${t.exportCSV||'CSV'}</button></div>`
  );
  const brandingCard=card(t.branding,
    `<div class="callout">${state.lang==='ar'?'إعدادات هوية الشركة والطباعة تحفظ في إعدادات النظام.':'Branding and printing identity are persisted in system settings.'}</div>`
  );
  return pageHead(t.settings,state.lang==='ar'?'إدارة المستخدمين وتهيئة النظام والتكاملات':'Users, system configuration and tools')+
    `<div class="tabs"><button class="tab active">${t.users}</button><button class="tab">${t.systemConfig}</button><button class="tab">${t.printing}</button><button class="tab">${t.dataTools}</button></div>`+
    `<div class="grid grid-2" style="margin-top:14px">${usersCard}${systemCard}</div>`+
    `<div class="grid grid-3" style="margin-top:16px">${unitsCard}${appearanceCard}${printCard}</div>`+
    `<div class="grid grid-2" style="margin-top:16px">${dataCard}${brandingCard}</div>`;
}
