document.addEventListener('click',e=>{const p=e.target.closest('[data-page]');if(p){state.page=p.dataset.page;render();return}const a=e.target.closest('[data-action]');if(a){if(a.dataset.action==='v13-toggle-password'){const input=document.querySelector('#auth-form [data-password-input]');if(input){const visible=input.type==='password';input.type=visible?'text':'password';a.setAttribute('aria-pressed',String(visible));a.setAttribute('aria-label',visible?(state.lang==='ar'?'إخفاء كلمة المرور':'Hide password'):(state.lang==='ar'?'إظهار كلمة المرور':'Show password'));a.title=a.getAttribute('aria-label');a.innerHTML=visible?'<span aria-hidden="true">◉̸</span>':'<span aria-hidden="true">◉</span>';input.focus()}return}handleAction(a.dataset.action)}if(e.target.matches('[data-close-modal]'))closeModal()});
