  const categoryRows=categories.map(c=>`<tr><td>${esc(c.code)}</td><td>${esc(c.name)}</td><td>${esc(c.description||'—')}</td><td>${c.is_active===false?c10Badge('INACTIVE'):c10Badge('ACTIVE')}</td><td><button class="btn small" data-action="v8-edit-category:${c.id}" ${orshapCanPermission('action:item:update')?'':'disabled'}>${esc(t.edit)}</button></td></tr>`);
  const shelfRows=shelves.map(sh=>`<tr><td>${esc(sh.code)}</td><td>${esc(v5Find('storage_areas',sh.storage_area_id)?.name||'—')}</td><td>${esc(sh.full_path||'—')}</td><td><button class="btn small" data-action="v8-edit-shelf:${sh.id}" ${orshapCanPermission('action:facility:manage')?'':'disabled'}>${esc(t.edit)}</button> <button class="btn small" data-action="v8-print-shelf:${sh.id}">${esc(t.print)}</button></td></tr>`);
