async function c10LoadTransitStock(){
  const client=await window.orshapSupabaseReady;
  if(!client)throw new Error(state.lang==='ar'?'اتصال قاعدة البيانات غير متاح.':'Database connection is unavailable.');
  const result=await client.from('stock_in_transit').select('*').order('dispatched_at',{ascending:false});
  if(result.error)throw result.error;
  state.c10TransitRows=Array.isArray(result.data)?result.data:[];
  render();
  toast(state.lang==='ar'?'تم تحميل '+state.c10TransitRows.length+' تحويلات قيد النقل':'Loaded '+state.c10TransitRows.length+' in-transit transfers','success');
}
async function c10LoadCanonicalStockSummary(){
  const filters=state.c10ReportFilters||{};
  const start=filters.from?new Date(filters.from+'T00:00:00').toISOString():'1970-01-01T00:00:00Z';
  const end=filters.to?new Date(filters.to+'T23:59:59').toISOString():new Date().toISOString();
  if(start>end)throw new Error(state.lang==='ar'?'نطاق التاريخ غير صحيح.':'Invalid date range.');
  const client=await window.orshapSupabaseReady;
  if(!client)throw new Error(state.lang==='ar'?'اتصال قاعدة البيانات غير متاح.':'Database connection is unavailable.');
  const result=await client.rpc('get_stock_summary_by_storage_area',{p_start_date:start,p_end_date:end,p_warehouse_id:filters.warehouse||null,p_storage_area_id:filters.area||null,p_category_id:filters.category||null});
  if(result.error)throw result.error;
  state.c10ServerStockSummaryRows=Array.isArray(result.data)?result.data:[];
  render();
  toast(state.lang==='ar'?`تم تحميل ${state.c10ServerStockSummaryRows.length} صفًا من قاعدة البيانات`:`Loaded ${state.c10ServerStockSummaryRows.length} rows from the database`,'success');
}
