function c10Export(){const kind=state.c10ReportKind||'movements',headers=c10ReportHeaders(kind),rows=c10ReportRows(kind,state.c10ReportFilters||{});if(!headers.length){toast(state.lang==='ar'?'افتح تقريرًا أولًا قبل التصدير.':'Open a report before exporting.','warning');return}const csv='\ufeff'+[headers,...rows].map(r=>r.map(x=>`"${String(x??'').replace(/"/g,'""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`orshap-${kind}-${Date.now()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
