function c10SyncQueueSnapshot(){
  const sid=String(state.session?.id||'anonymous');let master=[],outbox=[],legacy=v5All('sync_queue');
  try{const x=JSON.parse(localStorage.getItem('orshap_master_outbox_v1:'+sid)||'[]');if(Array.isArray(x))master=x}catch(_){}
  try{const x=JSON.parse(localStorage.getItem('orshap_tx_outbox_v1:'+sid)||'[]');if(Array.isArray(x))outbox=x}catch(_){}
  const rows=[];
  for(const x of master)rows.push({id:x.operation_id,source:'master',table:x.table,operation:x.kind,status:x.status||'PENDING',attempts:x.attempts||0,error:x.last_error||'',time:x.created_at||'',record:x.id});
  for(const x of outbox)if(x.status!=='SYNCED')rows.push({id:x.operation_id,source:'transaction',table:'transactions + transaction_lines',operation:x.kind||'transaction_bundle',status:x.status||'PENDING',attempts:x.attempts||0,error:x.last_error||'',time:x.created_at||'',record:x.payload?.transaction?.reference_no||x.payload?.transaction?.id||''});
  for(const x of legacy.filter(x=>!x.synced))rows.push({id:x.operation_id,source:'legacy',table:x.table||'unknown',operation:x.operation||'unknown',status:x.error_details?'ERROR':'PENDING',attempts:x.retry_count||0,error:x.error_details||'Legacy queue: no safe handler is registered',time:x.timestamp||'',record:''});
  return rows;
}
function c10Sync(){c10Ensure();const all=c10SyncQueueSnapshot(),pending=all.filter(x=>x.status!=='SYNCED'),conflicts=all.filter(x=>['CONFLICT','ERROR'].includes(x.status));const ar=state.lang==='ar';const rows=pending.map(x=>`<tr><td>${esc(String(x.id||'').slice(0,8)||'—')}</td><td>${esc(x.source)}</td><td>${esc(x.table)}</td><td>${esc(x.operation)}</td><td>${esc(x.status)}</td><td>${x.attempts}</td><td>${esc(x.error||'—')}</td><td>${esc(x.time?new Date(x.time).toLocaleString():'—')}</td></tr>`);return pageHead(ar?'المزامنة وحل التعارضات':'Synchronization & conflict resolution',ar?'عرض موحّد لطوابير المسودات والتغييرات المحلية':'Unified view of draft and local-change queues',`${conflicts.some(x=>x.status==='ERROR'&&x.source!=='legacy')?`<button class="btn ghost" data-action="c10-retry-errors">↻ ${ar?'إعادة محاولة الأخطاء':'Retry errors'}</button>`:''}<button class="btn primary" data-action="c10-sync-now">↻ ${ar?'مزامنة الآن':'Sync Now'}</button>`)+`<div class="grid grid-3">${stat(ar?'معلقة':'Pending',pending.length,ar?'تنتظر المزامنة':'Awaiting sync','↻')}${stat(ar?'أخطاء / تعارضات':'Errors / Conflicts',conflicts.length,ar?'تحتاج مراجعة':'Need review','!')}${stat(ar?'الاتصال':'Online',navigator.onLine?(ar?'متصل':'YES'):(ar?'غير متصل':'NO'),ar?'حالة الشبكة فقط':'Network status only','◉')}</div><div class="callout" style="margin-top:14px">${ar?'لا تُعتمد أرصدة المخزون النهائية دون اتصال. مسودات المعاملات تُرسل عبر RPC آمن عند عودة الاتصال. عناصر الطابور القديم لا تُنفذ تلقائياً إذا لم يكن لها معالج آمن.':'Final stock balances are never posted offline. Transaction drafts are sent through the secure RPC after reconnection. Legacy queue items without a safe handler are not auto-executed.'}</div><div class="card" style="margin-top:14px">${table(['ID','Source','Table','Operation','Status','Attempts','Last error','Created'],rows,ar?'لا توجد عمليات معلقة':'No pending operations')}</div>`}
function c10RetryErrors(){const sid=String(state.session?.id||'anonymous');let n=0;for(const key of ['orshap_master_outbox_v1:'+sid,'orshap_tx_outbox_v1:'+sid]){try{const q=JSON.parse(localStorage.getItem(key)||'[]');if(!Array.isArray(q))continue;for(const op of q){if(op.status==='ERROR'){op.status='PENDING';op.last_error=null;n++}}localStorage.setItem(key,JSON.stringify(q))}catch(e){console.warn('Could not prepare queue retry',key,e)}}if(n){toast(state.lang==='ar'?`تمت إعادة ${n} عملية إلى قائمة المحاولة`:`${n} operation(s) queued for retry`,'success');c10DoSync()}else toast(state.lang==='ar'?'لا توجد أخطاء قابلة لإعادة المحاولة تلقائياً. التعارضات والسجل القديم تحتاج معالجة يدوية.':'No retryable errors. Conflicts and legacy queue entries require manual handling.','warning')}
async function c10DoSync(){if(!navigator.onLine){toast(state.lang==='ar'?'لا يوجد اتصال؛ ستبقى المسودات محفوظة محلياً':'Offline: drafts remain safely queued','warning');return}if(!state.session?.id||state.offlineSession){toast(state.lang==='ar'?'سجّل الدخول عبر الإنترنت أولاً لمزامنة العمليات':'Sign in online first to sync queued work','warning');return}try{loadingBar(true);await window.orshapV12?.syncOfflineMasterQueue?.();await window.orshapOutbox?.retry?.();await window.orshapV12?.refresh?.();render();const left=c10SyncQueueSnapshot().filter(x=>x.status!=='SYNCED');toast(left.length?(state.lang==='ar'?`اكتملت محاولة المزامنة؛ بقيت ${left.length} عملية للمراجعة`:`Sync attempted; ${left.length} operation(s) still need review`):(state.lang==='ar'?'اكتملت المزامنة':'Synchronization completed'),left.length?'warning':'success')}catch(e){toast((state.lang==='ar'?'فشلت المزامنة: ':'Sync failed: ')+(e?.message||String(e)),'error')}finally{loadingBar(false)}}

