  async function upd(table,id,row){if(!navigator.onLine)return offlineMasterMutation('update',table,id,row)||{data:null,error:new Error('This operation requires an internet connection')};const s=await R();return s.from(table).update(row).eq('id',id).select().single();}
  async function del(table,id){if(!navigator.onLine)return offlineMasterMutation('delete',table,id,{})||{data:null,error:new Error('This operation requires an internet connection')};const s=await R();return s.from(table).delete().eq('id',id);}
  async function upsert(table,row,conflict='id'){if(!navigator.onLine&&OFFLINE_MASTER_TABLES.has(table)){const pk=table==='system_settings'?'key':'id',found=(V5_DB[table]||[]).find(x=>x[pk]===row[pk]);return found?offlineMasterMutation('update',table,row[pk],row):offlineMasterMutation('insert',table,null,row)}const s=await R();return s.from(table).upsert(row,{onConflict:conflict}).select();}
  function applyOfflineMasterOverlay(){const q=masterQueueRead();for(const op of q){if(!OFFLINE_MASTER_TABLES.has(op.table))continue;const pk=op.pk||'id',rows=Array.isArray(V5_DB[op.table])?V5_DB[op.table]:(V5_DB[op.table]=[]),i=rows.findIndex(x=>x[pk]===op.id);if(op.kind==='delete'){if(i>=0)rows.splice(i,1)}else if(op.kind==='insert'){if(i<0)rows.push({...op.row});else rows[i]={...rows[i],...op.row}}else if(op.kind==='update'){if(i>=0)rows[i]={...rows[i],...op.row};else rows.push({...op.row})}}}
  async function syncOfflineMasterQueue(){if(!navigator.onLine||!state.session?.id||state.offlineSession||!window.orshapSupabase)return;const q=masterQueueRead();if(!q.length)return;const s=await R();let changed=false;for(let i=0;i<q.length;){const op=q[i];if(op.status==='CONFLICT'){i++;continue}try{let r;if(op.kind==='insert'){const row={...op.row};if(op.table==='stocktake_lines')delete row.variance;r=await s.from(op.table).upsert(row,{onConflict:op.pk||'id'})}else if(op.kind==='update'){const patch={...op.row};delete patch.variance;if(op.table==='stocktake_lines')delete patch[op.pk||'id'];r=await s.from(op.table).update(patch).eq(op.pk||'id',op.id)}else if(op.kind==='delete')r=await s.from(op.table).delete().eq(op.pk||'id',op.id);else{q.splice(i,1);changed=true;continue}if(r?.error)throw r.error;q.splice(i,1);changed=true}catch(e){op.attempts=(op.attempts||0)+1;op.last_error=String(e?.message||e);op.status=/network|fetch|timeout|offline|load failed/i.test(op.last_error)?'PENDING':'ERROR';changed=true;if(op.status==='PENDING')break;i++}}if(changed)masterQueueWrite(q);if(!q.length){try{await v12PullCore();showToast(v12Translate('تمت مزامنة تغييرات البيانات الأساسية','Offline master-data changes synchronized'),'success')}catch(e){console.warn('Master queue synced; refresh skipped',e)}}else if(q.some(x=>x.status==='ERROR'))showToast(v12Translate('توجد تغييرات محلية تحتاج مراجعة في شاشة المزامنة','Some offline changes need review in Sync'),'warning')}
