  async function v12RequestTransactionReference(requestId){
    const form=document.getElementById('v12-tx-form');
    if(!form||state.v12ReferenceRequestId!==requestId)return;
    const input=form.querySelector('[name="reference_no"]');
    if(!input||input.value.trim())return;
    state.v12ReferencePending=requestId;
    const retryButton=document.querySelector('#modal-root [data-action="v12-tx-retry-reference"]');
    if(retryButton)retryButton.disabled=true;
    try{
      const result=await Promise.race([
        rpc('next_transaction_reference',{}),
        new Promise((_,reject)=>setTimeout(()=>reject(new Error(state.lang==='ar'?'انتهت مهلة توليد رقم السند. أعد المحاولة.':'Reference generation timed out. Retry the request.')),8000))
      ]);
      if(result.error)throw result.error;
      if(typeof result.data!=='string'||!result.data.trim())throw new Error('Database did not return a transaction reference');
      if(state.v12ReferenceRequestId!==requestId)return;
      const current=document.querySelector('#v12-tx-form [name="reference_no"]');
      if(!current||current.value.trim())return;
      state.v12TxMeta={...(state.v12TxMeta||{}),reference_no:result.data};
      current.value=result.data;
      current.dispatchEvent(new Event('input',{bubbles:true}));
      const retryNow=document.querySelector('#modal-root [data-action="v12-tx-retry-reference"]');
      if(retryNow)retryNow.hidden=true;
    }catch(e){
      if(state.v12ReferenceRequestId!==requestId||!document.getElementById('v12-tx-form'))return;
      say((state.lang==='ar'?'تعذر توليد رقم سند آمن: ':'Could not generate a safe transaction reference: ')+(e?.message||String(e)),'Reference generation failed','error');
    }finally{
      if(state.v12ReferencePending===requestId){
        state.v12ReferencePending=null;
        const retryNow=document.querySelector('#modal-root [data-action="v12-tx-retry-reference"]');
        if(retryNow&&!retryNow.hidden&&!state.v12TxMeta?.reference_no)retryNow.disabled=false;
      }
    }
  }
  
