    const lineTable=isMovement?`<div class="v13-txn-lines">${lineHtml}</div>`:`<div class="table-wrap v13-txn-lines-table"><table class="table"><thead><tr><th>${state.lang==='ar'?'الصنف':'Item'}</th><th>${t.warehouse}</th><th>${state.lang==='ar'?'منطقة التخزين':'Storage area'}</th><th>${t.shelf}</th><th>${state.lang==='ar'?'الإدارة المالكة':'Stock owner'}</th><th>${t.qty}</th><th>${state.lang==='ar'?'التشغيلة':'Batch'}</th><th>${t.actions}</th></tr></thead><tbody>${lineHtml||`<tr><td colspan="8" class="muted">${state.lang==='ar'?'لم تتم إضافة أصناف بعد':'No items added yet'}</td></tr>`}</tbody></table></div>`;
