function showToast(message,type='success'){try{toast(message,type)}catch(e){console[type==='error'?'error':'log'](message)}}
function canPermission(key){const p=state.session?.profile||{},role=String(state.session?.role||p.role||'').toUpperCase();if(['SUPER_ADMIN','ADMIN','MANAGER','WAREHOUSE_MANAGER'].includes(role))return true;const custom=Array.isArray(p.custom_permissions)?p.custom_permissions:[];const rolePerms=(window.orshapV12?.state?.remoteState?.role_permissions||[]).filter(x=>x.role_name===role).map(x=>x.permission_key);return custom.includes(key)||rolePerms.includes(key)||custom.includes('*')}
