function canManageSettings(){return ['SUPER_ADMIN','ADMIN','MANAGER'].includes(String(state.session?.role||state.session?.profile?.role||'').toUpperCase())}
function noAccessView(){return `<section class="v13-noaccess card"><div class="v13-noaccess-icon">⛨</div><h2>${tx('لا توجد صلاحية وصول للمستودعات','No warehouse access assigned')}</h2><p>${tx('هذا الحساب لا يملك مستودعاً مخصصاً. اطلب من المدير تعيين مستودع واحد على الأقل. تم إخفاء بيانات التشغيل احتياطياً.','This account has no assigned warehouse. Ask an administrator to assign at least one warehouse. Operational data is hidden by default.')}</p><button class="btn danger" data-action="logout">${T().logout}</button></section>`}
