function titleForPage(id){const t=T();return t[id]||({about:tx('حول النظام','About'),sync:tx('المزامنة','Synchronization'),users:tx('المستخدمون','Users'),units:tx('الوحدات','Units'),audit:tx('سجل التدقيق','Audit log')})[id]||id}
function currentPageActions(){const id=state.page,items=[];if(id==='inventory')items.push(['v12-add-item','＋ '+tx('صنف جديد','Add item')]);if(id==='transactions')items.push(['v12-new-tx','＋ '+tx('معاملة جديدة','New transaction')]);if(id==='facilities')items.push(['v12-add-wh','＋ '+tx('مستودع','Warehouse')]);if(id==='stocktake')items.push(['c10-start-session','＋ '+tx('جلسة جرد','Stocktake')]);/* Reports expose their own contextual export action after a report is selected. */return items;}
