function allSearchRows(q){q=String(q||'').trim().toLowerCase();if(q.length<2)return [];const out=[],add=(kind,rows,label,route,sub)=>rows.forEach(x=>{const hay=[label(x),x.code,x.item_number,x.reference_no,x.name,x.name_ar,x.name_en,x.email,x.action,x.entity,x.status].filter(Boolean).join(' ').toLowerCase();if(hay.includes(q))out.push({kind,id:x.id,title:label(x)||x.code||x.reference_no||x.email||kind,sub:sub(x),route,record:x})});add('items',v5All('items'),x=>x.code||x.name_en||x.name_ar,'inventory',x=>`${x.name_ar||x.name_en||''} · ${x.base_unit||''}`);add('transactions',v5All('transactions'),x=>x.reference_no,'transactions',x=>`${x.transaction_type||''} · ${x.status||''}`);add('users',v5All('profiles'),x=>x.name||x.email,'settings',x=>`${x.email||''} · ${x.role||''}`);add('audit',v5All('audit_logs'),x=>x.action,'reports',x=>`${x.entity||''} · ${x.reference||''}`);add('warehouses',v5All('warehouses'),x=>x.name||x.code,'facilities',x=>x.code||'');return out.slice(0,12)}
