function updateTxPreview(){
  const f=document.getElementById('v12-tx-form');
  if(!f||!window.orshapV12?.calculateDraft)return;
  const o=Object.fromEntries(new FormData(f).entries());
  const calc=window.orshapV12.calculateDraft(o);
  const set=(sel,val)=>{const el=document.querySelector(sel);if(el)el.textContent=String(val??'—')};
  set('[data-v13-preview-reference]',o.reference_no||'—');
  set('[data-v13-preview-type]',v13DisplayTransactionType(o.transaction_type));
  set('[data-v13-preview-count]',calc.lines.length);
  set('[data-v13-preview-total]',calc.total.toLocaleString(undefined,{maximumFractionDigits:3}));
  const doc=document.querySelector('[data-v13-preview-doc-lines]');
  const eq=document.querySelector('[data-v13-equations]');
  const impact=document.querySelector('[data-v13-stock-impact]');
  const err=document.querySelector('[data-v13-tx-errors]');
  if(doc){doc.innerHTML=calc.lines.map(l=>`<tr><td>${esc(l.itemCode||'—')}</td><td>${esc(l.shelfCode||'—')}</td><td>${Number(l.quantity||0).toLocaleString(undefined,{maximumFractionDigits:3})}</td><td>${esc(l.unit||'')}</td></tr>`).join('')||`<tr><td colspan="4">${tx('أضف سطراً لمعاينة المستند','Add a line to preview the document')}</td></tr>`;}
  if(eq){eq.innerHTML=calc.lines.map(l=>`<div class="v13-equation-row"><b>${esc(l.itemCode||tx('صنف','Item'))}</b><span>${Number(l.before||0).toLocaleString(undefined,{maximumFractionDigits:3})} ${l.inbound?'+':'−'} ${Number(l.quantity||0).toLocaleString(undefined,{maximumFractionDigits:3})} = <strong>${Number(l.after||0).toLocaleString(undefined,{maximumFractionDigits:3})}</strong></span></div>`).join('')||`<small>${tx('ستظهر المعادلات هنا بعد اختيار الصنف والكمية.','Equations appear after selecting an item and quantity.')}</small>`;}
  if(impact){impact.innerHTML=calc.lines.map(l=>`<div class="v13-impact-row ${l.error?'invalid':l.inbound?'in':'out'}"><span>${esc(l.itemCode||'—')} · ${esc(l.shelfCode||'—')}</span><b>${Number(l.before||0).toLocaleString(undefined,{maximumFractionDigits:3})} → ${Number(l.after||0).toLocaleString(undefined,{maximumFractionDigits:3})}</b></div>`).join('')||`<small>${tx('لا يوجد تأثير محسوب بعد.','No stock impact calculated yet.')}</small>`;}
  if(err){err.hidden=calc.errors.length===0;err.innerHTML=calc.errors.map(e=>`<div>⚠ ${esc(e)}</div>`).join('');}
  const save=document.querySelector('[data-action="v12-tx-save"]');
  if(save){save.disabled=!calc.valid;save.title=calc.valid?'':(calc.errors[0]||tx('أكمل بيانات المعاملة','Complete the transaction'));}
}
