/* v13.9.3: explicit local snapshot implementation. This is a browser-readable backup, not an Auth/DB-admin dump. */
const V1393_BACKUP_TABLES = ['profiles','system_settings','audit_logs','warehouses','storage_areas','administrative_departments','item_categories','shelves','items','stock','transactions','transaction_lines','stocktake_sessions','stocktake_lines','stocktake_logs','stock_transfers','stock_transfer_orders','archive_movements','archive_balances','permissions','role_permissions','units','item_unit_conversions','inventory_ledger','transaction_audit','transaction_ledger','sync_log'];
function v135Backup(){
  const stamp=new Date().toISOString().replace(/[:.]/g,'-');
  const local={};
  try { for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i); if(!k)continue; if(/^(orshap_|wms_|v5_|warehouse)/i.test(k)){const v=localStorage.getItem(k);try{local[k]=JSON.parse(v)}catch(_){local[k]=v}}} } catch(e){throw new Error('تعذر قراءة التخزين المحلي: '+(e.message||e));}
  const localTables={};
  try { if(typeof V5_DB==='object'&&V5_DB) for(const [k,v] of Object.entries(V5_DB)) if(Array.isArray(v)) localTables[k]=v; } catch(_){}
  const report={created_at:new Date().toISOString(),application:'ORSHAP WMS',format_version:2,scope:'browser-readable snapshot; does not include Supabase Auth passwords or inaccessible server-side data',tables:{},localStorage_keys:Object.keys(local).length,warnings:[]};
  for(const t of V1393_BACKUP_TABLES){const rows=localTables[t];if(Array.isArray(rows)){report.tables[t]={source:'local-cache',count:rows.length,data:rows};}}
  report.localStorage=local;
  report.warnings.push('هذه النسخة لا تشمل كلمات مرور Supabase أو مفاتيح service_role أو سجلات auth.users المحمية.');
  report.warnings.push('الجداول التي لا تسمح RLS للحساب بقراءتها قد لا تكون موجودة في اللقطة المحلية.');
  const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json;charset=utf-8'});
  const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='orshap-wms-local-backup-'+stamp+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);
  showToast(state.lang==='ar'?'تم تنزيل لقطة البيانات المحلية. راجع التحذيرات داخل ملف JSON.':'Local data snapshot downloaded. Review warnings inside the JSON file.','success');
  return {ok:true,tables:Object.keys(report.tables).length,localStorageKeys:report.localStorage_keys};
}
window.v1393BackupSchedule = function v1393BackupSchedule(){
  const key='orshap_backup_schedule_v1';
  let cfg={enabled:false,interval:'day'};try{cfg={...cfg,...JSON.parse(localStorage.getItem(key)||'{}')}}catch(_){}
  return `<section class="card v1393-backup-schedule"><div class="card-head"><b>${tx('النسخ الاحتياطي التلقائي المحلي','Automatic local backup')}</b></div><div class="card-body"><p class="page-subtitle">${tx('يعمل أثناء بقاء التطبيق مفتوحاً فقط؛ المتصفح لا يضمن جدولة النسخ عند إغلاقه.','Runs only while the app remains open; browsers do not guarantee backups while closed.')}</p><label class="field"><span>${tx('التكرار','Interval')}</span><select id="v1393-backup-interval"><option value="hour" ${cfg.interval==='hour'?'selected':''}>${tx('كل ساعة','Hourly')}</option><option value="day" ${cfg.interval==='day'?'selected':''}>${tx('كل يوم','Daily')}</option></select></label><label class="field"><span><input type="checkbox" id="v1393-backup-enabled" ${cfg.enabled?'checked':''}> ${tx('تفعيل النسخ أثناء تشغيل التطبيق','Enable while app is open')}</span></label><button class="btn primary" data-action="v1393-save-backup-schedule">${tx('حفظ الجدولة','Save schedule')}</button></div></section>`;
};
function v1393StartBackupSchedule(){
  if(window.__orshapBackupScheduleTimer)clearInterval(window.__orshapBackupScheduleTimer);
  let cfg={};try{cfg=JSON.parse(localStorage.getItem('orshap_backup_schedule_v1')||'{}')}catch(_){}
  if(!cfg.enabled)return;
  const interval=cfg.interval==='hour'?3600000:86400000;
  window.__orshapBackupScheduleTimer=setInterval(()=>{try{v135Backup()}catch(e){console.warn('Scheduled local backup failed',e)}},interval);
}

