function trfOrderRows(){const all=v5All('stock_transfers').slice().sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||''))),parents=new Map(v5All('stock_transfer_orders').map(o=>[o.id,o])),groups=new Map();for(const x of all){const key=x.transfer_order_id||x.id;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(x)}return [...groups.entries()].map(([id,lines])=>{const parent=parents.get(id),lineStatus=lines.some(x=>['IN_TRANSIT','PARTIALLY_RECEIVED','RETURN_IN_TRANSIT'].includes(x.status))?(lines.some(x=>x.status==='RETURN_IN_TRANSIT')?'RETURN_IN_TRANSIT':lines.some(x=>x.status==='PARTIALLY_RECEIVED')?'PARTIALLY_RECEIVED':'IN_TRANSIT'):lines.every(x=>['RECEIVED','COMPLETED'].includes(x.status))?'RECEIVED':lines.some(x=>x.status==='REJECTED')?'REJECTED':lines[0].status;return {id,lines,reference:parent?.reference_no||(lines[0].reference_no||'—').replace(/-L\d{3}$/,''),source:parent?.source_warehouse_id||lines[0].source_warehouse_id,destination:parent?.destination_warehouse_id||lines[0].destination_warehouse_id,status:parent?.status||lineStatus,created_at:parent?.created_at||lines[0].created_at,kind:parent?.operation_type||(String(lines[0].notes||'').includes('WAREHOUSE_RETURN')?'WAREHOUSE_RETURN':'TRANSFER')}})}
