/* v13.9.58: explicit voucher review gate before any transaction write.
   The original form stays mounted underneath the review overlay, so saveTx()
   receives the exact form data that the user reviewed. */
(function installTransactionReviewGate(){
  if(window.__orshapTxReviewGateInstalled)return;
  window.__orshapTxReviewGateInstalled=true;
  let overlay=null;
  const escText=v=>typeof escv==='function'?escv(v):String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  function openReview(){
    const form=document.getElementById('v12-tx-form');
    if(!form) return;
    const o=Object.fromEntries(new FormData(form).entries());
    const type=String(o.transaction_type||'GRN').toUpperCase();
    const movement=['TRANSFER','RETURN_TO_LOCATION','RETURN_TO_SUPPLIER','RETURN_FROM_USAGE','RETURN_FROM_CUSTOMER'].includes(type);
    const drafts=state.v12TxLines||[];
    const calc=window.orshapV12?.calculateDraft ? window.orshapV12.calculateDraft(o) : null;
    const lines=(calc?.lines||drafts.map((l,i)=>({
      itemCode:v5Find('items',l.item_id)?.code||'—',
      itemName:v5Find('items',l.item_id)?.name_ar||v5Find('items',l.item_id)?.name_en||'',
      shelfCode:v5Find('shelves',l.shelf_id)?.code||'—',
      quantity:l.quantity,
      administrative_department_id:l.administrative_department_id
    })));
    const recipient=v5Find('administrative_departments',o.recipient_department_id);
    const rows=lines.map((l,i)=>{
      const owner=v5Find('administrative_departments',l.administrative_department_id||drafts[i]?.administrative_department_id);
      return '<tr><td>'+ (i+1) +'</td><td><b>'+escText(l.itemCode||l.item_code||'—')+'</b><div>'+escText(l.itemName||'')+'</div></td><td>'+escText(l.shelfCode||'—')+'</td><td>'+escText(l.quantity??drafts[i]?.quantity??'—')+'</td><td>'+escText(owner?.name||'—')+'</td></tr>';
    }).join('');
    const errors=calc?.errors||[];
    const isIssue=type==='ISSUE';
    const isReceipt=type==='GRN';
    const total=calc?.total??drafts.reduce((n,l)=>n+Number(l.quantity||0),0);
    overlay=document.createElement('div');
    overlay.className='modal-backdrop v13-tx-review-backdrop';
    overlay.setAttribute('role','dialog');
    overlay.setAttribute('aria-modal','true');
    overlay.setAttribute('aria-label',state.lang==='ar'?'معاينة السند قبل التأكيد':'Voucher review before confirmation');
    overlay.innerHTML='<section class="modal v13-tx-review-modal"><header class="modal-head"><div class="modal-title">'+(state.lang==='ar'?'مراجعة السند قبل الحفظ':'Review voucher before saving')+'</div><button type="button" class="icon-btn" data-review-cancel aria-label="'+(state.lang==='ar'?'العودة':'Back')+'">×</button></header><div class="modal-body"><div class="callout">'+(state.lang==='ar'?'راجع بيانات السند وبنوده والإدارة المالكة لكل بند. لن يتغير المخزون قبل نجاح الاعتماد في قاعدة البيانات.':'Review the voucher, its lines, and each line’s stock-owning department. Stock is not changed until database approval succeeds.')+'</div><div class="form-grid"><div class="field"><label>'+(state.lang==='ar'?'رقم المرجع':'Reference')+'</label><div>'+escText(o.reference_no||'—')+'</div></div><div class="field"><label>'+(state.lang==='ar'?'نوع المعاملة':'Transaction type')+'</label><div>'+escText(typeof v13DisplayTransactionType==='function'?v13DisplayTransactionType(type):type)+'</div></div><div class="field"><label>'+(state.lang==='ar'?'المورد':'Supplier')+'</label><div>'+escText(o.supplier||'—')+'</div></div><div class="field"><label>'+(state.lang==='ar'?'المستلم الفعلي':'Physical receiver')+'</label><div>'+escText(o.receiver_name||'—')+'</div></div><div class="field"><label>'+(state.lang==='ar'?'الجهة المستلمة للصرف':'Issue recipient department')+'</label><div>'+escText(recipient?.name||'—')+'</div></div><div class="field"><label>'+(state.lang==='ar'?'إجمالي الكمية':'Total quantity')+'</label><div>'+escText(Number(total||0).toLocaleString())+'</div></div></div><div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>'+(state.lang==='ar'?'الصنف':'Item')+'</th><th>'+(state.lang==='ar'?'الرف':'Shelf')+'</th><th>'+(state.lang==='ar'?'الكمية':'Quantity')+'</th><th>'+(state.lang==='ar'?'الإدارة المالكة':'Stock owner')+'</th></tr></thead><tbody>'+ (rows||'<tr><td colspan="5">'+(state.lang==='ar'?'لا توجد بنود':'No lines')+'</td></tr>') +'</tbody></table></div>'+(errors.length?'<div class="callout warning">'+errors.map(e=>'<div>⚠ '+escText(e)+'</div>').join('')+'</div>':'')+(isIssue&&!o.recipient_department_id?'<div class="callout warning">'+(state.lang==='ar'?'الجهة المستلمة للصرف غير محددة.':'Issue recipient department is missing.')+'</div>':'')+(isIssue&&!String(o.receiver_name||'').trim()?'<div class="callout warning">'+(state.lang==='ar'?'اسم المستلم الفعلي إلزامي للصرف.':'Physical receiver name is required for issues.')+'</div>':'')+(isReceipt&&!String(o.supplier||'').trim()?'<div class="callout warning">'+(state.lang==='ar'?'اسم المورد إلزامي للتوريد.':'Supplier is required for goods receipts.')+'</div>':'')+(movement?'<p class="muted">'+(state.lang==='ar'?'ستُنفذ حركة التحويل أو الاسترداد عبر دالة قاعدة البيانات المختصة.':'Transfer/return will be processed by the corresponding database function.')+'</p>':'')+'<div class="form-actions"><button type="button" class="btn ghost" data-review-cancel>'+(state.lang==='ar'?'العودة للتعديل':'Back to edit')+'</button><button type="button" class="btn primary" data-review-confirm '+((errors.length||!drafts.length||(isIssue&&(!o.recipient_department_id||!String(o.receiver_name||'').trim()))||(isReceipt&&!String(o.supplier||'').trim()))?'disabled':'')+'>'+(state.lang==='ar'?'تأكيد وحفظ الطلب':'Confirm and save request')+'</button></div></div></section>';
    document.body.appendChild(overlay);
    overlay.addEventListener('click',e=>{
      if(e.target===overlay||e.target.closest('[data-review-cancel]')){overlay.remove();overlay=null;return;}
      if(!e.target.closest('[data-review-confirm]'))return;
      if(e.target.closest('[data-review-confirm]').disabled)return;
      overlay.remove();overlay=null;
      state.__v13TxReviewConfirmed=true;
      try {
        const result=handleAction('v12-tx-save');
        if(result&&typeof result.finally==='function')result.finally(()=>{state.__v13TxReviewConfirmed=false});
        else state.__v13TxReviewConfirmed=false;
      } catch(err) {state.__v13TxReviewConfirmed=false;showToast(err?.message||String(err),'error');}
    });
  }
  document.addEventListener('click',function(e){
    const btn=e.target.closest('[data-action="v12-tx-save"]');
    if(!btn)return;
    if(state.__v13TxReviewConfirmed){state.__v13TxReviewConfirmed=false;return;}
    e.preventDefault();e.stopImmediatePropagation();
    openReview();
  },true);
})();

